/// An option GCC 16.2 keeps as another name for an option: its warning
/// and what it stands for. Sorted by option.
pub(crate) static ALIASES: &[(&str, &str, &str)] = &[
    (
        "-mfused-madd",
        "'-mfused-madd' is deprecated; use '-ffp-contract=' instead",
        "-ffp-contract=fast",
    ),
    (
        "-mintel-syntax",
        "'-mintel-syntax' and '-mno-intel-syntax' are deprecated; use '-masm=intel' and '-masm=att' instead",
        "-masm=intel",
    ),
    (
        "-mno-fused-madd",
        "'-mfused-madd' is deprecated; use '-ffp-contract=' instead",
        "-ffp-contract=off",
    ),
    (
        "-mno-intel-syntax",
        "'-mintel-syntax' and '-mno-intel-syntax' are deprecated; use '-masm=intel' and '-masm=att' instead",
        "-masm=att",
    ),
    ("-mno-sse5", "'-msse5' was removed", "-mno-avx"),
    ("-msse5", "'-msse5' was removed", "-mavx"),
];

/// The same for a prefix: `-mstore-max=V` is `-mmove-max=V`.
pub(crate) static PREFIX_ALIASES: &[(&str, &str, &str)] = &[(
    "-mstore-max=",
    "'-mstore-max=' is deprecated; use '-mmove-max=' instead",
    "-mmove-max=",
)];

/// `-malign-NAME=N`: obsolete in GCC 16.2 for `-falign-NAME=2^N`.
pub(crate) static OBSOLETE_ALIGN: &[&str] = &["functions", "jumps", "loops"];
